sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    var blkTskType = g_scratchpad.blkTskRelated;
    if (blkTskType === 'Checker') {
        var decision = g_form.getValue('decision_reason');
        var gajax = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils"); //getting count of checker and checker to be rejected tasks
        gajax.addParam("sysparm_name", "getCountOfRejectTask");
        gajax.addParam("sysparm_bulkid", g_form.getUniqueValue());
        gajax.getXMLAnswer(response);

    }

    function response(answer) {
        var count = answer;
        if (count > 0 && decision == 'Other') {
            g_form.setMandatory('comments', true);
        } else {
            g_form.setMandatory('comments', false);
        }
    }
}
